#!/usr/bin/env bash
# SWE-Odyssey oracle for one segment (generated by `odyssey compile`).
# Used only by Harbor's oracle agent, which uploads this directory to /solution.
set -euo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

SOLUTION_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ODYSSEY_WORKDIR"
# Same git hygiene as setup.sh: no global/system config, no hooks or fsmonitor.
GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null \
    git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
    apply --whitespace=nowarn "$SOLUTION_DIR/gold.patch"
